def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        safe_bid = min(budget, DAILY_SALARY * 0.35)
        if hp <= 2 or no_water_days >= 2:
            safe_bid = min(budget, DAILY_SALARY * 0.8)
        return max(0, safe_bid)

    prev_bids = []
    prev_bids_named = []
    dangerous_pressure = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
            prev_bids_named.append((bid, opp))
            if bid > dangerous_pressure:
                dangerous_pressure = bid

    alive_count = len(alive) + 1
    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    per_capita = supply / float(alive_count)

    urgent = False
    if hp <= 2 or no_water_days >= 2:
        urgent = True
    elif hp <= 4 and no_water_days >= 1:
        urgent = True

    very_tight = per_capita < WATER_REQ * 0.55
    tight = per_capita < WATER_REQ * 0.8

    base = DAILY_SALARY * (0.34 + 0.22 * scarcity)

    if tight:
        base += DAILY_SALARY * 0.12
    if very_tight:
        base += DAILY_SALARY * 0.12

    if prev_bids:
        top_bid = max(prev_bids)
        moderate_bid = sorted(prev_bids)[int(len(prev_bids) / 2)]

        if urgent:
            target = max(base + 18, top_bid + 2)
        else:
            if top_bid >= 150:
                target = base
            elif top_bid >= 110:
                target = max(base, moderate_bid + 2)
            elif top_bid >= 75:
                target = max(base, top_bid + 1.5)
            else:
                target = max(base, top_bid + 1)
    else:
        target = base

    rich_aggressive = 0
    for opp in alive:
        if opp.get('budget', 0) >= budget and opp.get('hp', 0) >= 6:
            prev = opp.get('previous_trace', {})
            pbid = prev.get('bid') if prev else None
            if pbid is not None and pbid >= 100:
                rich_aggressive += 1

    if rich_aggressive >= 2 and not urgent:
        target -= 10

    if urgent:
        target = max(target, DAILY_SALARY * 0.9)
        if very_tight:
            target = max(target, 115)
    else:
        if day <= 3 and hp >= 8 and no_water_days == 0 and dangerous_pressure >= 120:
            target = min(target, DAILY_SALARY * 0.45)

    reserve_floor = 0
    days_left = max(0, 10 - day)
    if days_left >= 3 and not urgent:
        reserve_floor = DAILY_SALARY * 1.2
    max_affordable = max(0, budget - reserve_floor)

    if urgent:
        max_affordable = budget

    bid = min(target, max_affordable)

    if bid < 0:
        bid = 0

    if urgent and budget > 0:
        bid = max(bid, min(budget, DAILY_SALARY * 0.9))

    if hp >= 7 and no_water_days == 0 and dangerous_pressure >= 150 and not very_tight:
        bid = min(bid, DAILY_SALARY * 0.4)

    return max(0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    base_bid = DAILY_SALARY * 0.6

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 1.2
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.9

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid > base_bid:
            if my_status['hp'] <= 3:
                base_bid = highest_prev_bid + DAILY_SALARY * 0.2
            elif my_status['hp'] <= 5:
                base_bid = highest_prev_bid + DAILY_SALARY * 0.1
            else:
                base_bid = highest_prev_bid + DAILY_SALARY * 0.05
        else:
            base_bid = max(base_bid, highest_prev_bid + 1.0)

    theoretical_water_slots = day_context['supply'] / WATER_REQ

    if theoretical_water_slots < 1.0 or (theoretical_water_slots < 1.5 and num_alive_opponents >= 1):
        if my_status['hp'] <= 3:
            base_bid = max(base_bid, DAILY_SALARY * 1.5)
        elif my_status['hp'] <= 5:
            base_bid = max(base_bid, DAILY_SALARY * 1.0)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.75)

    final_bid = min(my_status['budget'], base_bid)

    if my_status['hp'] <= 2 and my_status['budget'] > 0 and final_bid < 1.0:
        final_bid = min(my_status['budget'], 1.0)

    return max(0.0, final_bid)
